#include <unity.h>
#include "lamp_sync.h"

using lamp::SenderArbiter;
using lamp::kSenderDesktop;
using lamp::kSenderLegacy;
using lamp::kSenderPhone;

static constexpr uint32_t kFresh = 500;

void setUp(void) {}
void tearDown(void) {}

void test_first_packet_is_accepted_whatever_its_priority(void) {
  SenderArbiter a;
  TEST_ASSERT_TRUE(a.accept(kSenderLegacy, 1000, kFresh));
}

void test_lower_priority_is_ignored_while_higher_is_fresh(void) {
  SenderArbiter a;
  TEST_ASSERT_TRUE(a.accept(kSenderDesktop, 1000, kFresh));
  TEST_ASSERT_FALSE(a.accept(kSenderPhone, 1010, kFresh));
  TEST_ASSERT_TRUE(a.accept(kSenderDesktop, 1020, kFresh));
  TEST_ASSERT_FALSE(a.accept(kSenderPhone, 1499, kFresh));   // 距上一个 Mac 包 479 ms
}

// 被拒的低级包不能刷新时间：否则手机一直在发，Mac 停了也永远轮不到手机
void test_rejected_packets_do_not_extend_the_lock(void) {
  SenderArbiter a;
  a.accept(kSenderDesktop, 1000, kFresh);
  for (uint32_t t = 1010; t < 1500; t += 10) TEST_ASSERT_FALSE(a.accept(kSenderPhone, t, kFresh));
  TEST_ASSERT_TRUE(a.accept(kSenderPhone, 1500, kFresh));
}

void test_lower_priority_takes_over_after_higher_goes_stale(void) {
  SenderArbiter a;
  a.accept(kSenderDesktop, 1000, kFresh);
  TEST_ASSERT_TRUE(a.accept(kSenderPhone, 1500, kFresh));    // 正好断流 500 ms
  TEST_ASSERT_EQUAL_UINT8(kSenderPhone, a.prio);
  TEST_ASSERT_TRUE(a.accept(kSenderPhone, 1510, kFresh));    // 接管后照常收
}

void test_higher_priority_preempts_immediately(void) {
  SenderArbiter a;
  a.accept(kSenderPhone, 1000, kFresh);
  TEST_ASSERT_TRUE(a.accept(kSenderDesktop, 1005, kFresh));
  TEST_ASSERT_FALSE(a.accept(kSenderPhone, 1010, kFresh));
}

void test_same_priority_is_always_accepted(void) {
  SenderArbiter a;
  a.accept(kSenderPhone, 1000, kFresh);
  TEST_ASSERT_TRUE(a.accept(kSenderPhone, 1001, kFresh));
}

void test_legacy_packets_rank_below_phone(void) {
  SenderArbiter a;
  a.accept(kSenderPhone, 1000, kFresh);
  TEST_ASSERT_FALSE(a.accept(kSenderLegacy, 1010, kFresh));
}

void test_millis_wraparound(void) {
  SenderArbiter a;
  a.accept(kSenderDesktop, 0xFFFFFF00u, kFresh);
  TEST_ASSERT_FALSE(a.accept(kSenderPhone, 0x00000010u, kFresh));   // 回绕后只过了 272 ms
  TEST_ASSERT_TRUE(a.accept(kSenderPhone, 0x00000200u, kFresh));    // 768 ms
}

int main(int, char **) {
  UNITY_BEGIN();
  RUN_TEST(test_first_packet_is_accepted_whatever_its_priority);
  RUN_TEST(test_lower_priority_is_ignored_while_higher_is_fresh);
  RUN_TEST(test_rejected_packets_do_not_extend_the_lock);
  RUN_TEST(test_lower_priority_takes_over_after_higher_goes_stale);
  RUN_TEST(test_higher_priority_preempts_immediately);
  RUN_TEST(test_same_priority_is_always_accepted);
  RUN_TEST(test_legacy_packets_rank_below_phone);
  RUN_TEST(test_millis_wraparound);
  return UNITY_END();
}
